"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["50180"],{80509(e){e.exports=JSON.parse('{"id":"V4-087","slug":"best-execution","term":"Best Execution","also_known_as":[],"difficulty":"Advanced","definition":"Best execution is the obligation of brokers and investment firms to take sufficient steps to obtain the best possible result for their clients when carrying out trades, considering factors such as price, costs, speed and likelihood of execution.","explanation":["When a broker executes a trade for a client, it can often choose between different exchanges, trading venues and market makers. Best execution rules require it to act in the client\u2019s interest when making these choices.","Price is usually the most important factor, but not the only one. Firms must also consider costs, the speed and likelihood of execution and settlement, the size of the order and any other relevant factors. For retail clients, the total cost, combining price and costs, is often given the greatest weight.","For example, a broker routing a client\u2019s order to a venue offering a slightly worse price because it receives a payment from that venue could breach best execution requirements.","Best execution is required by regulators in many markets, including under MiFID II in the European Union and FINRA rules in the United States. Firms must have execution policies, monitor the quality of their execution and review it regularly."],"note":"","total":1725,"prev":{"slug":"best-case-scenario","term":"Best-Case Scenario"},"next":{"slug":"beta","term":"Beta"}}')}}]);